// Company-supplied registration records reviewed 31 October 2026.
// Publish business identifiers only; original certificates and personal annexures stay private.
const companyRegistration = Object.freeze({
 legalName:'BANDEVI GLOBAL GROUP PRIVATE LIMITED',
 cin:'U79110HR2026PTC152314',gstin:'06AAPCB2996N1ZU',
 incorporated:'30 October 2026',gstEffective:'31 October 2026',
 address:'SCO 63, First Floor, Sector 23/23A, behind petrol pump, Palam Vihar, Gurugram, Haryana 122017, India'
});
function companyRegistrationSection(primary=false){
 const r=companyRegistration;
 return `<section class="section" id="company-registration" aria-labelledby="company-registration-title"><div class="container"><div class="section-head single"><span class="eyebrow">Company registration</span><${primary?'h1':'h2'} id="company-registration-title">Know the company behind your project.</${primary?'h1':'h2'}><p class="lead">${r.legalName}</p><p>An Indian private limited company, incorporated on ${r.incorporated}, with GST registration effective ${r.gstEffective}.</p></div><div class="grid cols-3"><article class="card"><h3>Corporate identity</h3><p><strong>CIN</strong><br><span style="overflow-wrap:anywhere">${r.cin}</span></p><p>Certificate of Incorporation issued by the Ministry of Corporate Affairs.</p></article><article class="card"><h3>GST registration</h3><p><strong>GSTIN</strong><br><span style="overflow-wrap:anywhere">${r.gstin}</span></p><p>GST REG-06 certificate records regular registration from ${r.gstEffective}.</p></article><article class="card"><h3>Business address on supplied records</h3><p>${r.address}</p><p><a href="/offices/#gurugram-office">Office and visit information</a></p></article></div><p>Details transcribed from company-supplied incorporation and GST certificates, reviewed 31 October 2026. Use the official portals to check current company and taxpayer records.</p><div class="inline-actions"><a class="button dark" href="https://www.mca.gov.in/" target="_blank" rel="noopener noreferrer">Check company records at MCA ↗</a><a class="button light" href="https://services.gst.gov.in/services/searchtp" target="_blank" rel="noopener noreferrer">Check taxpayer records at GST ↗</a></div><p class="muted" style="margin-top:16px">Search using the CIN or GSTIN above. Registration identifies the named business; project scope, provider approvals and commercial terms are confirmed separately in your proposal.</p></div></section>`;
}
function buyerRecordBoundaries(){return `<section class="section mist"><div class="container"><h2>Clear records. Clear project responsibilities.</h2><div class="grid cols-3"><article class="card"><h3>Written scope and handover</h3><p>Confirm deliverables, milestones, price and currency, source-code and data rights, acceptance and support before work starts.</p><a href="/how-we-work/#before-you-hire">Review the buyer questions</a></article><article class="card"><h3>Evidence you can inspect</h3><p>Explore BANDEVI's internal implementation record and clearly labelled sample workflows. Customer references are shared only with permission.</p><a href="/projects/bandevi-website/">Inspect our own implementation</a></article><article class="card"><h3>Remote international delivery</h3><p>Discuss UK, US, UAE and Singapore projects with the team in India. Overseas service coverage does not imply a staffed local office.</p><a href="/international/">Review international delivery</a></article></div><p>These documents do not establish ISO certification, Udyam registration, sector permissions, audited financial figures, workforce totals or customer results.</p><div class="inline-actions"><a class="button dark" href="/contact-us/">Discuss your project</a><a class="text-link" href="/project-brief/">Prepare a project brief</a></div></div></section>`;}
const companyRecordsPage = ()=>companyRegistrationSection(true)+buyerRecordBoundaries();
pageRenderers.trust=companyRecordsPage;
pageRenderers.officialFacts=()=>companyRegistrationSection(true)+`<section class="section mist"><div class="container"><h2>Published business information</h2><p>Website, app, CRM, ERP and travel-technology development services. Deliverables and integrations depend on the written proposal.</p><p><a href="mailto:sales@bandeviglobalgroup.com">sales@bandeviglobalgroup.com</a> · <a href="tel:+917011040474">+91 70110 40474</a></p><p>No verified staff total or financial figure is published. Project attribution and customer references require applicable evidence and permission.</p><a href="/assets/bandevi-global-group-official-facts.json">Read the structured company record</a></div></section>`+buyerRecordBoundaries();
pageRenderers.proof=()=>companyRegistrationSection(true)+buyerRecordBoundaries();
pageRenderers.evidenceRegister=()=>companyRegistrationSection(true)+`<section class="section mist"><div class="container"><h2 id="registration-evidence-title">What these records support</h2><div class="table-wrap" tabindex="0" role="region" aria-labelledby="registration-evidence-title"><table><thead><tr><th>Record</th><th>Document-supported detail</th><th>Verification route</th></tr></thead><tbody><tr><td>Certificate of Incorporation</td><td>Legal name, private limited structure, CIN and incorporation on 30 October 2026.</td><td>Ministry of Corporate Affairs company records</td></tr><tr><td>GST REG-06</td><td>Legal name, GSTIN, principal business address and registration effective 31 October 2026.</td><td>GST portal taxpayer search</td></tr><tr><td>Other credentials and results</td><td>Not established by these two documents.</td><td>Request the applicable issuer record or customer-approved evidence.</td></tr></tbody></table></div><p>The supplied documents have been reviewed for the fields shown here. A live registry-status or digital-signature validation is not represented as completed.</p><p><a href="/assets/bandevi-global-group-evidence-register.txt">Text register</a> · <a href="/assets/bandevi-global-group-evidence-register.json">Structured register</a></p></div></section>`+buyerRecordBoundaries();
const registrationBeforeHero=hero;
hero=(page,data)=>['trust','officialFacts','proof','evidenceRegister'].includes(page)?'':registrationBeforeHero(page,data);
const homepageBeforeRegistration=pageRenderers.home;
pageRenderers.home=()=>{
 const t=document.createElement('template');t.innerHTML=homepageBeforeRegistration();
 const target=t.content.querySelector('#buyer-trust .container');
 if(!target)throw Error('Homepage buyer trust section missing');
 const summary=document.createElement('aside');summary.className='card';summary.dataset.companyRegistrationSummary='';summary.setAttribute('aria-label','Company registration');
 summary.innerHTML=`<p style="color:#1b2a3d"><strong>${companyRegistration.legalName}</strong><br>Incorporated in India · GST registered</p><p style="overflow-wrap:anywhere;color:#1b2a3d">CIN ${companyRegistration.cin} · GSTIN ${companyRegistration.gstin}</p><a class="text-link" href="/trust-licences-certifications/#company-registration">Review company registration and verification links ↗</a>`;
 target.append(summary);return t.innerHTML;
};

